head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05000";
scwin.select_new_write = null;
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.select_new_write = $c.util.getComponent('select_new_write');
        scwin.init_rowCopy();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05000.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.prelistPageForm || { elements: [] });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05000.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05000' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(prelist vs prelistpage) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_currentPageSize_onchange
 * @description slc_currentPageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_currentPageSize_onchange = function(e){
    try {
        scwin.search();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05000.slc_currentPageSize_onchange' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["trnsmYn"] === 'N') { await scwin.prelistSub(r["bzProcsNo"], r["billLstSaveStatCd"]); return; }
        if (r["trnsmYn"] === 'N') { await scwin.prelistDel(r["bzProcsNo"]); return; }
        await scwin.prelistEnt(r["bzProcsNo"], r["billLstSaveStatCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_New_Cancel_onclick
 * @description btn_New_Cancel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_Cancel_onclick = function(e){
    try {
        scwin.newCancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05000.btn_New_Cancel_onclick' }); }
};

/**
 * @method
 * @name btn_New_onclick
 * @description btn_New 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function(e){
    try {
        await scwin.newPrelistEntReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05000.btn_New_onclick' }); }
};

/**
 * @method
 * @name btn_New_2_onclick
 * @description btn_New_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_2_onclick = async function(e){
    try {
        await scwin.newPrelistEntReq(5)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05000.btn_New_2_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_51_onclick
 * @description krxpage_pagenavigator_51 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_51_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_PrelistEntReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_51.page' }); } scwin.search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_PrelistEnt
 * @description Prelist Ent 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_PrelistEnt = async function () {
    const sbmOptions = {
        id: "tx_fn_PrelistEnt",
        method: "post",
        action: "/list/prelist.do",
        ref: "dma_PrelistEntReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_New
 * @description New 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_New = async function () {
    const sbmOptions = {
        id: "tx_fn_New",
        method: "post",
        action: "/list/prelist.do",
        ref: "dma_NewReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_PrelistSub
 * @description Prelist Sub 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_PrelistSub = async function () {
    const sbmOptions = {
        id: "tx_fn_PrelistSub",
        method: "post",
        action: "/list/prelistPage.do",
        ref: "dma_PrelistSubReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_PrelistDel
 * @description Prelist Del 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_PrelistDel = async function () {
    const sbmOptions = {
        id: "tx_fn_PrelistDel",
        method: "post",
        action: "/list/prelistPage.do",
        ref: "dma_PrelistDelReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_pageList_fmt_status
 * @description grd page List fmt status 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_status = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "trnsmYn") ?? '') : '');
        if (v === 'Y') { return String((dl && dl.getCellData ? dl.getCellData(r, "status") : '') ?? ''); }
        if (v === 'N') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: status (image)'), String(data ?? '')) + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.status" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pageList_fmt_column6
 * @description grd page List fmt column6 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_column6 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "trnsmYn") ?? '') : '');
        if (v === 'N') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: column6 (markup)'), String(data ?? '')) + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column6" }); return String(data ?? ''); }
};

/**
 * @method
 * @name prelistEnt
 * @description prelist Ent 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} billLstSaveStatCd billLstSaveStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistEnt = async function (bzProcsNo, billLstSaveStatCd) {
    $c.util.getComponent('dma_PrelistEntReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_PrelistEntReq').set('billLstSaveStatCd', billLstSaveStatCd);
    scwin.form.action = '/list/prelist.do';
    $c.util.getComponent('dma_PrelistEntReq').set('method', 'prelistSearch');
    await scwin.tx_fn_PrelistEnt();
};

/**
 * @method
 * @name newPrelistEntReq
 * @description new Prelist Ent Req 처리
 * @param {*} sVal sVal
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newPrelistEntReq = async function (sVal) {
    $c.util.getComponent('dma_PrelistEntReq').set('prelmInvstgComTpCd', sVal);
    $c.util.getComponent('dma_PrelistEntReq').set('billLstSaveStatCd', "0");
    $c.util.getComponent('dma_PrelistEntReq').set('trnsmYn', "N");
    scwin.form.action = '/list/prelist.do';
    $c.util.getComponent('dma_PrelistEntReq').set('method', 'prelistSearch');
    await scwin.tx_fn_New();
};

/**
 * @method
 * @name newDisplay
 * @description new Display 처리
 * @returns {void}
 * @hidden N
 */
scwin.newDisplay = function () {
    scwin.select_new_write.setStyle("display", "block");
};

/**
 * @method
 * @name newCancel
 * @description new Cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.newCancel = function () {
    scwin.select_new_write.setStyle("display", "none");
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {void}
 * @hidden N
 */
scwin.search = function () {
    $c.util.getComponent('dma_PrelistEntReq').set('method', 'prelistPageSearch');
    scwin.form.submit();
};

/**
 * @method
 * @name prelistSub
 * @description prelist Sub 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} billLstSaveStatCd billLstSaveStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistSub = async function (bzProcsNo, billLstSaveStatCd) {
    if ((billLstSaveStatCd) < 9) {
        await $c.win.alert("회사채발행 또는 보호예수 페이지까지 입력을 하셔야만 제출 하실수 있습니다.\n\n해당사항이 없는 경우는 \n\n각  페이지에서 해당사항없음을 클릭해주세요.");
        return;
    }
    $c.util.getComponent('dma_PrelistEntReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_PrelistEntReq').set('trnsmYn', "Y");
    scwin.form.action = '/list/prelistPage.do';
    $c.util.getComponent('dma_PrelistEntReq').set('method', 'prelistPageSub');
    await scwin.tx_fn_PrelistSub();
};

/**
 * @method
 * @name prelistDel
 * @description prelist Del 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistDel = async function (bzProcsNo) {
    $c.util.getComponent('dma_PrelistEntReq').set('bzProcsNo', bzProcsNo);
    scwin.form.action = '/list/prelistPage.do';
    $c.util.getComponent('dma_PrelistEntReq').set('method', 'prelistPageDelete');
    await scwin.tx_fn_PrelistDel();
};
